import React, { useRef, useEffect, useState } from "react";
import { HERO_LABELS, BRAND } from "./Content";
import { ArrowDownRight, Sparkles, Crown, Gem, Truck } from "lucide-react";

export default function Hero({ onOpenQuote }) {
  const hostRef = useRef(null);
  const [activeLabel, setActiveLabel] = useState(null);

  useEffect(() => {
    const onMove = (e) => {
      if (!hostRef.current) return;
      const r = hostRef.current.getBoundingClientRect();
      const nx = (e.clientX - r.left) / r.width;
      const ny = (e.clientY - r.top) / r.height;

      let best = null;
      let bestDist = Infinity;
      HERO_LABELS.forEach((l) => {
        const dx = l.x - nx * 100;
        const dy = l.y - ny * 100;
        const d = dx * dx + dy * dy;
        if (d < bestDist) { bestDist = d; best = l; }
      });
      if (bestDist < 30 * 30) setActiveLabel(best);
      else setActiveLabel(null);
    };
    const el = hostRef.current;
    if (el) { el.addEventListener("mousemove", onMove); el.addEventListener("mouseleave", () => setActiveLabel(null)); }
    return () => { if (el) { el.removeEventListener("mousemove", onMove); } };
  }, []);

  return (
    <section ref={hostRef} className="relative w-full" style={{ background: "#ffffff" }}>

      {/* TOP DECORATIVE SECTION - Full Width Wedding Image */}
      <div className="relative w-full overflow-hidden" style={{ height: "70vh", minHeight: 500, maxHeight: 700 }}>
        {/* Background Image */}
        <img
          src="https://images.unsplash.com/photo-1519741497674-611481863552?w=1920&auto=format&fit=crop"
          alt="Wedding Decor"
          className="absolute inset-0 w-full h-full object-cover"
        />

        {/* Overlay */}
        <div className="absolute inset-0" style={{ background: "linear-gradient(180deg, rgba(255,255,255,0.85) 0%, rgba(255,255,255,0.6) 50%, rgba(255,255,255,0.9) 100%)" }} />

        {/* Gold Border Top */}
        <div className="absolute top-0 left-0 w-full h-1" style={{ background: "linear-gradient(90deg, transparent 0%, #d4af37 50%, transparent 100%)" }} />

        {/* Product Hover Zones - Only visible on hover */}
        {HERO_LABELS.map((label) => (
          <div
            key={label.id}
            className="absolute cursor-pointer transition-all duration-300"
            style={{
              left: `${label.x}%`,
              top: `${label.y}%`,
              transform: "translate(-50%, -50%)",
              opacity: activeLabel?.id === label.id ? 1 : 0,
              zIndex: 20,
            }}
          >
            <div className="px-4 py-2 rounded-full text-sm font-semibold whitespace-nowrap"
              style={{
                background: "#d4af37",
                color: "#ffffff",
                boxShadow: "0 4px 20px rgba(212,175,55,0.4)"
              }}>
              {label.title}
            </div>
          </div>
        ))}

        {/* Hero Text OVER the image */}
        <div className="absolute inset-0 z-10 flex flex-col justify-center px-6 md:px-12 lg:px-24">
          <div className="max-w-4xl">
            {/* Location Badge */}
            <div className="flex items-center gap-3 mb-6">
              <div className="w-12 h-px" style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }} />
              <span className="text-xs tracking-[0.3em] uppercase font-semibold" style={{ color: "#b8902a" }}>Ludhiana, Punjab</span>
            </div>

            {/* Main Title */}
            <h1 className="serif gold-shimmer leading-[0.9] tracking-tight mb-4" style={{ fontSize: "clamp(48px, 10vw, 140px)", fontWeight: 400 }}>
              D SAJAWAT
            </h1>

            {/* Tagline */}
            <div className="flex items-center gap-3 mb-4">
              <Crown size={20} color="#d4af37" />
              <p className="serif text-xl md:text-3xl" style={{ color: "#1a080a", fontStyle: "italic", fontWeight: 400 }}>
                {BRAND.tagline}
              </p>
            </div>
          </div>
        </div>

        {/* Bottom Gradient */}
        <div className="absolute bottom-0 left-0 w-full h-24" style={{ background: "linear-gradient(to bottom, transparent, #ffffff)" }} />
      </div>

      {/* BOTTOM CONTENT SECTION - Below the image */}
      <div className="relative w-full px-6 md:px-12 lg:px-24 py-16 md:py-20" style={{ background: "#ffffff" }}>
        <div className="max-w-6xl mx-auto">

          {/* Subtitle */}
          <p className="text-base md:text-lg max-w-3xl mb-8" style={{ color: "rgba(26,8,10,0.7)", lineHeight: 1.8 }}>
            Premium fabrics for weddings & events. Trusted by India's top decorators with Pan India delivery.
            From elegant table covers to stunning ceiling drapes - we bring your vision to life.
          </p>

          {/* Features Pills */}
          <div className="flex flex-wrap gap-4 mb-10">
            <div className="flex items-center gap-2 px-5 py-3 rounded-full" style={{ background: "linear-gradient(135deg, #fffdf5, #fff9ed)", border: "1px solid rgba(212,175,55,0.4)", boxShadow: "0 2px 12px rgba(212,175,55,0.1)" }}>
              <Gem size={18} color="#d4af37" />
              <span className="text-sm font-semibold" style={{ color: "#1a080a" }}>Premium Quality</span>
            </div>
            <div className="flex items-center gap-2 px-5 py-3 rounded-full" style={{ background: "linear-gradient(135deg, #fffdf5, #fff9ed)", border: "1px solid rgba(212,175,55,0.4)", boxShadow: "0 2px 12px rgba(212,175,55,0.1)" }}>
              <Truck size={18} color="#d4af37" />
              <span className="text-sm font-semibold" style={{ color: "#1a080a" }}>Pan India Delivery</span>
            </div>
            <div className="flex items-center gap-2 px-5 py-3 rounded-full" style={{ background: "linear-gradient(135deg, #fffdf5, #fff9ed)", border: "1px solid rgba(212,175,55,0.4)", boxShadow: "0 2px 12px rgba(212,175,55,0.1)" }}>
              <Crown size={18} color="#d4af37" />
              <span className="text-sm font-semibold" style={{ color: "#1a080a" }}>Bulk Orders</span>
            </div>
          </div>

          {/* CTA Buttons */}
          <div className="flex flex-wrap gap-4">
            <a href="#collections" className="btn-gold text-lg px-10 py-4">
              <Sparkles size={20} strokeWidth={1.6} />
              Explore Our Collection
            </a>
            <button onClick={onOpenQuote} className="btn-ghost text-lg px-10 py-4" type="button">
              Get a Quote
              <ArrowDownRight size={20} strokeWidth={1.6} />
            </button>
          </div>

          {/* Hover Hint */}
          <div className="mt-12 flex items-center gap-3">
